#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/zbus/zbus.h>
#include <zephyr/zbus/zbus_messages.h>

/* The subscriber thread has the highest priority, so the publisher thread
 * must be elevated to this priority.
 */
#define SUB_THR_PRIO 2
#define START_PRIO 5
#define STACK_SIZE (1024 + CONFIG_TEST_EXTRA_STACK_SIZE)

static atomic_t sub1_level;
static atomic_t msub1_level;
static int pub_prio_inside_pub_sub;

ZBUS_CHAN_DEFINE(prio_chan, /* Name */
		 struct zbus_test_msg, /* Message type */
		 NULL, /* Validator */
		 NULL, /* User data */
		 ZBUS_OBSERVERS(sub1, msub1), /* observers */
		 ZBUS_MSG_INIT(0) /* Initial value {0} */
		 );

/* sub1 is a listener, its callback is executed in the publisher's context */
static void sub1_cb(const struct zbus_channel *chan)
{
	const struct zbus_test_msg *msg;

	if (zbus_chan_claim(chan, K_NO_WAIT) == 0) {
		msg = zbus_chan_const_msg(chan);
		atomic_set(&sub1_level, msg->level);
		printk("sub1 level: %d\n", msg->level);

		/* This is the correct place to check the publisher's priority,
		 * as it is boosted for the duration of the zbus_chan_pub() call.
		 */
		pub_prio_inside_pub_sub = k_thread_priority_get(k_current_get());
		zbus_chan_finish(chan);
	}
}

ZBUS_LISTENER_DEFINE(sub1, sub1_cb);

/* msub1 is a subscriber with a dedicated thread */
static void msub1_thread(void)
{
	const struct zbus_channel *chan;
	const struct zbus_test_msg *msg;

	while (1) {
		if (zbus_sub_wait(&msub1, &chan, K_FOREVER) == 0) {
			msg = zbus_chan_const_msg(chan);
			atomic_set(&msub1_level, msg->level);
			printk("msub1 level: %d\n", msg->level);
		}
	}
}

ZBUS_SUBSCRIBER_DEFINE(msub1, 4);
K_THREAD_DEFINE(msub1_tid, STACK_SIZE, msub1_thread, NULL, NULL, NULL, SUB_THR_PRIO, 0, 0);

static void *hlp_priority_boost_setup(void)
{
	k_thread_access_grant(k_current_get(), &msub1_tid);

	return NULL;
}

static void hlp_priority_boost_before(void *fixture)
{
	atomic_set(&sub1_level, 0);
	atomic_set(&msub1_level, 0);
	pub_prio_inside_pub_sub = -1;

	/* Let msub1_thread run to wait for a message */
	k_sleep(K_MSEC(200));
}

ZTEST(hlp_priority_boost, test_priority_elevation)
{
	struct zbus_test_msg msg = {.level = 0};
	int initial_prio = k_thread_priority_get(k_current_get());

	/* Set the test thread priority to be lower than the subscriber */
	k_thread_priority_set(k_current_get(), START_PRIO);

	printk("sub1 level: %d\n", atomic_get(&sub1_level));
	printk("msub1 level: %d\n", atomic_get(&msub1_level));

	zassert_equal(atomic_get(&sub1_level), 0);
	zassert_equal(atomic_get(&msub1_level), 0);

	msg.level = 1;
	zbus_chan_pub(&prio_chan, &msg, K_MSEC(200));

	/* Let msub1_thread run and process the message */
	k_sleep(K_MSEC(200));

	zassert_equal(atomic_get(&sub1_level), 1);
	zassert_equal(atomic_get(&msub1_level), 1);

	/* Check that priority was boosted to the highest priority subscriber's priority.
	 * This check is on a value captured inside the listener callback.
	 */
	zassert_equal(pub_prio_inside_pub_sub, SUB_THR_PRIO,
		      "priority during publish was %d, expected %d",
		      pub_prio_inside_pub_sub, SUB_THR_PRIO);

	/* Check that priority was restored after publishing */
	int prio = k_thread_priority_get(k_current_get());

	zassert_equal(prio, START_PRIO, "priority not restored, is %d", prio);

	/* Restore initial priority */
	k_thread_priority_set(k_current_get(), initial_prio);
}

ZTEST_SUITE(hlp_priority_boost, NULL, hlp_priority_boost_setup, hlp_priority_boost_before, NULL,
	    NULL);
